// NATIVE MODULE CONTRACT: every module in runtime/<module>/ exposes
//   void iwn_register_<module>(v8::Isolate* isolate, v8::Local<v8::Context> ctx, v8::Local<v8::Object> natives);
// which installs its functions on the per-context natives object (JS: globalThis.__iwn.<module>). The table below
// is generated by runtime/cmake/registry.cmake from the modules the build found. The core calls every entry once
// per context, after its own natives exist (so a module may look up iwn::Runtime::From(isolate)) and before the
// core bootstrap and any prelude run.
#pragma once

#include <v8.h>

namespace iwn {

using NativeModuleRegisterFn = void (*)(v8::Isolate*, v8::Local<v8::Context>, v8::Local<v8::Object>);

struct NativeModuleEntry {
  const char* name;
  NativeModuleRegisterFn fn;
};

// Generated (iwn_module_registry.cc): terminated by {nullptr, nullptr}.
extern const NativeModuleEntry kNativeModules[];
extern const int kNativeModuleCount;

}  // namespace iwn
